def anti_shuffle(s):
    result = []
    words = s.split(' ')

    for word in words:
        sorted_word = ''.join(sorted(word))
        result.append(sorted_word)

    ordered_result = []
    index = 0

    for char in s:
        if char == ' ':
            ordered_result.append(' ')
        else:
            ordered_result.append(result[index])
            index += 1

    return ''.join(ordered_result)
